INSERT INTO dump_descriptions (base_key, description) VALUES ('noelevatorplantscream', 'Mutes the Elevator Plant scream by routing its sound reference to the package’s silent cue.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('vea-exp', 'Enemy rebalance: faster Cave Leech grabs, more Young Woodlouse health, revised Spider attacks and resistances, Plague infection changes, and shorter acid and goo puddle lifetimes.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('vea-exp_b2', 'Enemy rebalance: faster Cave Leech grabs, more Young Woodlouse health, revised Spider attacks and resistances, Plague infection changes, and shorter acid and goo puddle lifetimes. Also revises Spider Spitter AI.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('zip', 'Sets the Zipline Gun usable component’s interaction priority to -101 when the Zip actor begins play.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('customrooms_55_fixed_pe', 'Adds custom procedural cave rooms, including big rooms and Escort shaft challenges, and updates mission room pools to select custom-tagged rooms.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
