INSERT INTO dump_descriptions (base_key, description) VALUES ('customcavelayouts43', 'Adds custom cave rooms and retags existing rooms as CustomBig or CustomMedium so the Custom Layouts pool can select them.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('customcavelayouts_general_16.pak', 'Adds a Mod Hub page for choosing custom cave layouts and mission room-generation options across multiple mission types.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
