INSERT INTO dump_descriptions (base_key, description) VALUES ('no_carve_exploders', 'Sets the Exploder explosion crater dimensions to zero, preventing its explosion from carving terrain while retaining its damage call.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('noanimationvisible', 'Makes the enemy target HUD intro nearly instant (5×→999×); the temperature widget also changes its animation threshold from >0 to >-1 and its triggered intro rate from 3×→999×.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('transparentlasermark', 'Makes the small HUD bracket window’s normal border fully transparent; its alternate gold highlight color remains visible.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
